cases.source:
swimlane-beta TD
accDescr {
  multi line
  description
}

swimlane-beta LR
  subgraph L3["Customer"]
    E@{ label: "$$E=mc2$$" }
    B[tab	here]
  end
  D <--> B@{ label: "Plan" }
  D ==> D
  A ~~~ End["`**fa:fa-check step** md`"]
  C -.- End{tab	here}

swimlane-beta BT
  subgraph L2["Customer"]
    Ünï@{ shape: subroutine }
  end
  subgraph L1["Ünï Team"]
    A(((tab	here)))
    Start{{Ünï}}
    n_2>Ünï]
  end
  A -- "quoted" --> Start["**bold** step"]
  A -->|lbl| E@{ shape: documents, label: "tab	here" }
  C --- D@{ shape: delay }

swimlane-beta RL
  subgraph L1["Customer"]
    漢["x < y"]
    C{{Plan}}
  end
  subgraph L1["Ünï Team"]
    A[\a "quoted" step/]
  end
  C ==> C@{ shape: circle }
  Ünï ---> End[[$$E=mc2$$]]
  漢 -. dotted .-> n_2@{ shape: roundedRect }
  x1 --- D@{ label: "tab	here" }

swimlane-beta TB
  subgraph L3["Customer"]
    D@{ shape: Rect, label: "tab	here" }
    A{{Plan}}
  end
  subgraph L3["Ünï Team"]
    Ünï@{ label: "x < y" }
  end
  D --x B@{ label: "tab	here" }
  Ünï ---> n_2["`**x < y** md`"]
  Start ~~~ End["$$E=mc2$$"]

swimlane-beta LR
  subgraph L3["Customer"]
    Start:::hot
    A@{ shape: Rect, label: "Ünï" }
    D[/Ünï\]
  end
  subgraph L3["Ünï Team"]
    E@{ shape: win-pane }
    n_2{{$$E=mc2$$}}
    x1(Plan)
  end
  Ünï == thick ==> A[fa:fa-check step]
  x1 e1@--> C{tab	here}

swimlane-beta TB
  subgraph L2["Customer"]
    x1@{ shape: inv_trapezoid }
    x1["`****bold** step** md`"]
    Ünï[/x < y\]
  end
  x1 ---> n_2@{ shape: lean_right, label: "Ship it" }
  End --x|cross| End@{ shape: trapezoid }
  B ==> Start{Ship it}
  E == thick ==> E:::hot

swimlane-beta TB
  subgraph L1["Customer"]
    漢:::hot
    漢:::hot
  end
  End -. dotted .-> End{{$$E=mc2$$}}
  x1 <--> Start{{fa:fa-check step}}
  B --- A@{ shape: ellipse }
  C -. dotted .-> Start[\Run tests\]

swimlane-beta RL
  subgraph L1["Customer"]
    E@{ shape: brace, label: "Run tests" }
    x1@{ shape: bang, label: "Plan" }
  end
  Start -.- 漢([Plan])
  x1 -.-> Start@{ shape: documents, label: "Ünï" }

swimlane-beta LR
  subgraph L3["Customer"]
    B((fa:fa-check step))
  end
  End -->|lbl| E@{ shape: brace }
  B --- A{{a "quoted" step}}
  Start -. dotted .-> 漢(Plan)
  Ünï ---> 漢{$$E=mc2$$}

swimlane-beta TB
  subgraph L1["Customer"]
    End[/**bold** step\]
    B@{ shape: h-cyl }
  end
  C -.- 漢{{**bold** step}}
  A e2@==> D@{ shape: rect, label: "**bold** step" }

swimlane-beta LR
  subgraph L1["Customer"]
    x1["tab	here"]
  end
  subgraph L3["Ünï Team"]
    End[\Ünï\]
  end
  subgraph L1["Ops"]
    B@{ shape: h-cyl, label: "a "quoted" step" }
    D[(tab	here)]
    C{**bold** step}
  end
  Start -->|lbl| C{Ünï}
  Start ==> x1["`****bold** step** md`"]
  End --x|cross| E{Ünï}
  漢 == thick ==> End[\tab	here\]
  n_2 ~~~ 漢{{a "quoted" step}}
  D --x Ünï@{ label: "**bold** step" }

swimlane-beta LR
  subgraph L1["Customer"]
    漢
    E@{ shape: trapezoid, label: "long label that keeps going well past the wrapping width" }
    E@{ label: "tab	here" }
  end
  C -. dotted .-> A{$$E=mc2$$}
  Ünï --- B@{ label: "fa:fa-check step" }
  B e2@==> D[/tab	here\]
  A --o End(((Run tests)))
  D --> n_2[/a "quoted" step\]
  x1 -. dotted .-> B{{Ship it}}

swimlane-beta TB
  subgraph L3["Customer"]
    E:::hot
    E@{ shape: bogus }
    D@{ label: "long label that keeps going well past the wrapping width" }
  end
  subgraph L1["Ünï Team"]
    x1@{ shape: documents, label: "tab	here" }
    C[[**bold** step]]
    A[(tab	here)]
  end
  C --> Start{{a "quoted" step}}
  x1 -.- D[\a "quoted" step\]

swimlane-beta RL
  subgraph L1["Customer"]
    End@{ shape: rect }
  end
  subgraph L3["Ünï Team"]
    n_2{{Ünï}}
    E[[Ünï]]
    x1{{**bold** step}}
  end
  E e2@==> B((Plan))

swimlane-beta TB
  subgraph L3["Customer"]
    E[\tab	here\]
  end
  D e2@==> B[[**bold** step]]
  B -.- 漢[/a "quoted" step\]
  E --o C@{ shape: lean_right, label: "tab	here" }
  E -->|lbl| 漢@{ shape: brace, label: "$$E=mc2$$" }
  E --- E@{ label: "long label that keeps going well past the wrapping width" }
  E --o Start(((Run tests)))

swimlane-beta TB
  subgraph L3["Customer"]
    A{{long label that keeps going well past the wrapping width}}
  end
  subgraph L2["Ünï Team"]
    C[/**bold** step/]
  end
  Start -.-> x1@{ shape: lined-cylinder, label: "**bold** step" }
  Ünï --> B>$$E=mc2$$]
  Ünï -.- label .- C@{ shape: st-rect }

swimlane-beta LR
  subgraph L1["Customer"]
    B((tab	here))
  end
  End --o A[\a "quoted" step\]
  A -- text --> D{{long label that keeps going well past the wrapping width}}
  n_2 --- B{{long label that keeps going well past the wrapping width}}
  n_2 -.-> x1([long label that keeps going well past the wrapping width])
  Start e1@--> A@{ label: "x < y" }

swimlane-beta TB
  subgraph L1["Customer"]
    D{tab	here}
    End>a "quoted" step]
  end
  subgraph L2["Ünï Team"]
    x1@{ shape: hourglass, label: "$$E=mc2$$" }
  end
  n_2 ~~~ Ünï[fa:fa-check step]
  Start -. dotted .-> E@{ shape: documents, label: "x < y" }
  漢 --> D[/$$E=mc2$$/]
  x1 -- "quoted" --> E{Ship it}
  E --x|cross| 漢@{ shape: procs }

swimlane-beta TB
  subgraph L2["Customer"]
    n_2@{ label: "$$E=mc2$$" }
  end
  x1 --x|cross| B{{Run tests}}
  n_2 e1@--> D[\Run tests\]
  n_2 -.- label .- Start>Run tests]
  End ~~~ B@{ shape: circle, label: "$$E=mc2$$" }
  E --o B@{ label: "long label that keeps going well past the wrapping width" }
